import{_ as t,o,c as a,ag as i}from"./chunks/framework.DMVuHR7L.js";const p=JSON.parse('{"title":"Contributing","description":"","frontmatter":{},"headers":[],"relativePath":"devs/index.md","filePath":"devs/index.md","lastUpdated":1778523457000}'),s={name:"devs/index.md"};function r(n,e,d,l,c,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to &quot;Contributing&quot;">​</a></h1><p>WebLogcat is a small repo with a clear scope. These pages are the contributor-facing reference — what the codebase looks like, how it deploys, how to keep it in shape as it grows.</p><p>If you&#39;re an AI agent working on the repo, head to the <a href="./../bots/">For agents</a> section first — it has the contracts you need to honour. The pages here are still useful background, but the agent section is what tells you what to do.</p><h2 id="pages" tabindex="-1">Pages <a class="header-anchor" href="#pages" aria-label="Permalink to &quot;Pages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Use it for</th></tr></thead><tbody><tr><td><a href="./contributing">Contributing guide</a></td><td>Branch model, dev / build / lint / test commands, deploy gates</td></tr><tr><td><a href="./architecture">Architecture</a></td><td>Module map, top-level state, perf notes</td></tr><tr><td><a href="./deployment">Deployment</a></td><td>GitHub Pages topology, staging vs production, the gh-pages mechanic</td></tr><tr><td><a href="./release-plan">Release plan</a></td><td>Alpha → beta → GA promotion procedure with prereqs and steps</td></tr><tr><td><a href="./docs-conventions">Docs conventions</a></td><td>How this docs site is structured and what contributors must keep in sync</td></tr></tbody></table><h2 id="what-done-looks-like-for-a-task" tabindex="-1">What &quot;done&quot; looks like for a task <a class="header-anchor" href="#what-done-looks-like-for-a-task" aria-label="Permalink to &quot;What &quot;done&quot; looks like for a task&quot;">​</a></h2><ul><li><code>npm run typecheck</code>, <code>npm run lint</code>, <code>npm test</code>, <code>npm run build</code>, and <code>npm run e2e</code> all pass.</li><li>The behaviour was exercised by hand against the simulated stream (or, where relevant, against a real device — call out which one in the PR description).</li><li>New or changed user-facing behaviour has a corresponding update to the <a href="./../features/">features docs</a> — see <a href="./docs-conventions">docs-conventions</a>.</li><li>Core flows are exercised by tests — see <a href="./../bots/test-sync">test-sync rules</a> (these apply equally to humans).</li><li>A short note in the PR describing what changed and what was deliberately left for follow-up.</li><li>Auto-merge is armed (the repo has it enabled; CI gates the merge).</li></ul><h2 id="hard-constraints" tabindex="-1">Hard constraints <a class="header-anchor" href="#hard-constraints" aria-label="Permalink to &quot;Hard constraints&quot;">​</a></h2><ul><li><strong>TypeScript strict.</strong> No <code>any</code>. No <code>// @ts-ignore</code> without an inline comment explaining why.</li><li><strong>No new runtime dependencies</strong> without explicit approval. The list in <code>package.json</code> is intentionally short.</li><li><strong>Zero-cost infra.</strong> GitHub Pages + GitHub Actions only. Don&#39;t propose Vercel / Netlify / etc. without checking with the user.</li><li><strong>WebUSB requires HTTPS.</strong> The deploy target is HTTPS; local dev is <code>localhost</code>. Tests of the real transport must happen against the deployed staging URL — there are no devices in CI.</li><li><strong>High visual fidelity.</strong> Use <code>oklch()</code> for new colours — never hardcode hex.</li><li><strong>History is read-only.</strong> Don&#39;t rewrite past commit history. The noise (co-author footers, session URLs) is intentional; rewriting invalidates every existing PR/issue SHA link.</li></ul>',9)])])}const g=t(s,[["render",r]]);export{p as __pageData,g as default};
